import catalogJson from "./voice-catalog.json";
import { CALL_LANGUAGES, CALL_PROVIDERS } from "./call-voices";

// Generated by voice-worker/tools/make_voice_samples.py: every voice that was rendered, understood
// by speech recognition and kept, with a phone-quality sample for each language it speaks.
export type VoiceSample = { seconds: number; clarity: number; pitch_hz: number; pitch_sd?: number; file: string };

/** How much the voice's pitch moves while speaking: a monotone, "robotic" voice scores low. */
export function liveliness(sd?: number): string | null {
  if (sd == null) return null;
  return sd >= 3.2 ? "Lively" : sd >= 2.4 ? "Moderate" : "Flat";
}
export type CatalogVoice = {
  provider: "sarvam" | "elevenlabs" | "rumik" | "smallest" | "gnani";
  voice: string;
  label: string;
  model: string | null;
  gender: "female" | "male" | "unknown";
  languages: Record<string, VoiceSample>;
};

export const CATALOG = catalogJson as { generated: string; voices: CatalogVoice[] };

export const providerLabel = (p: string) => (CALL_PROVIDERS.find((x) => x.value === p)?.label ?? p);
export const languageLabel = (l: string) => CALL_LANGUAGES.find((x) => x.value === l)?.label ?? l;

export function findVoice(provider: string, voice: string, language: string) {
  const v = CATALOG.voices.find((x) => x.provider === provider && x.voice === voice);
  return v && v.languages[language] ? v : undefined;
}

// How the worker should speak a catalog voice: the model it needs and, for Rumik, the style note.
const RUMIK_STYLE: Record<string, string> = {
  "en-IN": "A warm, friendly, confident young woman speaking natural Indian English at a brisk, easy pace.",
  "hi-IN": "A warm, friendly, confident young woman speaking natural conversational Hindi at a brisk, easy pace.",
};
export function voiceConfig(v: CatalogVoice, language: string): Record<string, string | number> {
  if (v.provider === "sarvam") return { tts_model: v.model ?? "bulbul:v3", ...(v.voice === "kavitha_te_conversation" ? { tts_pace: 1.2 } : {}), ...(v.voice === "pooja" && language === "te-IN" ? { tts_pace: 1.1, tts_temperature: 0.9 } : {}) };
  if (v.provider === "smallest") return { tts_model: "lightning_v3.1_pro" };
  if (v.provider === "gnani") return { tts_model: "timbre-v3.0" };
  if (v.provider === "rumik") return { tts_model: "mulberry", tts_description: RUMIK_STYLE[language] ?? RUMIK_STYLE["en-IN"] };
  return {};
}
